{
  "title": "Pitch a Tent",
  "steps": [
    {
      "instruction": "Clear a flat rectangle of ground and remove sharp debris.",
      "companion": {
        "type": "zone",
        "shape": "rect",
        "size_m": 2.5,
        "stage": null
      },
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Face the tent door away from the prevailing wind.",
      "companion": {
        "type": "compass",
        "label": "Wind direction",
        "shape": null,
        "size_m": null,
        "stage": null
      },
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Unroll the tent body and lay out the poles.",
      "companion": {
        "type": "hologram_stage",
        "stage": 1
      },
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Assemble the poles and thread them through the tent sleeves.",
      "companion": {
        "type": "hologram_stage",
        "stage": 2
      },
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Lift the tent and secure the pole ends into the grommets.",
      "companion": {
        "type": "hologram_stage",
        "stage": 3
      },
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Drive stakes into the ground at each corner to secure the tent.",
      "companion": {
        "type": "timer",
        "duration_sec": 180,
        "label": "Staking time",
        "shape": null,
        "size_m": null,
        "stage": null
      },
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Drape the rainfly over the tent and clip it into place.",
      "companion": {
        "type": "hologram_stage",
        "stage": 4
      },
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Adjust the guy lines to pull the rainfly taut and stable.",
      "companion": {
        "type": "checklist",
        "items": [
          "All clips secured",
          "Guy lines taut",
          "Tent stable"
        ],
        "shape": null,
        "size_m": null,
        "stage": null
      },
      "safety": false,
      "warning": null
    }
  ]
}
